def backfill_invoice_numbers(apps_registry, schema_editor):
    """Give historical payments an invoice number based on their creation date."""
    import secrets

    Payment = apps_registry.get_model("payments", "Payment")
    used = set()
    for payment in Payment.objects.filter(invoice_number__isnull=True).iterator():
        while True:
            number = f"JCI-{payment.created_at:%Y%m%d}-{secrets.token_hex(3).upper()}"
            if number not in used:
                used.add(number)
                break
        payment.invoice_number = number
        update = {"invoice_number": number}
        if payment.status == "success":
            # Pre-existing successes were fulfilled by the old code path.
            update["paid_at"] = payment.updated_at
            update["fulfilled_at"] = payment.updated_at
        Payment.objects.filter(pk=payment.pk).update(**update)


